import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0029 — Workbench del vault nella Web UI (M9)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0029-web-workbench.md","filePath":"adr/0029-web-workbench.md"}'),l={name:"adr/0029-web-workbench.md"};function n(c,e,r,d,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0029-—-workbench-del-vault-nella-web-ui-m9" tabindex="-1">ADR-0029 — Workbench del vault nella Web UI (M9) <a class="header-anchor" href="#adr-0029-—-workbench-del-vault-nella-web-ui-m9" aria-label="Permalink to &quot;ADR-0029 — Workbench del vault nella Web UI (M9)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.3 (2026-11-02): §0.1, §0.3 (A-03), §1.1, §1.2, §1.7, §2.1, §2.1.1, §2.5, §2.6.1, §2.6.6, §2.8, §2.8.3, §3.5.1, §3.7, §3.8.1, §3.8.2, §3.8.6, §4.1–§4.5, App. A, C.2, C.3 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-29</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§0.1 punto 3, A-03, §2.8, §3.4.1, §3.8.1, §4.4, tabella rischi (Web UI anello debole dell&#39;E2EE); D-02, D-04, D-06; V-02; ADR-0020, ADR-0025, ADR-0030</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (A-03, §0.1, §2.8, §4.4, tabella rischi) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner; testo proposto in &quot;Proposta di modifica dello spec&quot;</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> I binding sono generati da <code>internal/app/gen/bindings</code> in <code>packages/workbench/wailsjs</code> (<code>task gen-wails</code>, senza la CLI di Wails) e l&#39;ABI per il frontend resta <code>window.go.app.*</code> e gli eventi <code>window.runtime.*</code>: ciò che l&#39;ADR descrive di <code>src/app/api.ts</code> e del mock e2e è ancora vero. Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Lo spec limita la Web UI del cloud a console amministrativa e area utente (quota, dispositivi, condivisioni, download ZIP): A-03 dice esplicitamente che &quot;la Web UI del cloud non è un editor&quot;. L&#39;owner chiede che dalla Web UI si possa gestire il vault <strong>con le stesse funzioni e le stesse interfacce del client desktop</strong> (<code>apps/desktop/frontend</code>), funzionanti e con lo stesso comportamento.</p><p>Vincoli che restano validi:</p><ul><li>il server non interpreta il contenuto e non fa merge (§3.4.1): ordina, versiona e conserva blob;</li><li>vault privati E2EE: path e contenuto opachi al server (D-02);</li><li>perimetro per-vault, nessuna funzione cross-vault (D-06);</li><li>architettura chiusa, niente CSS o <code>&lt;style&gt;</code> dell&#39;utente (V-02);</li><li>Excalidraw offline, senza richieste di rete.</li></ul><p>Stato del codice che rende la richiesta praticabile:</p><ul><li>il frontend desktop accede al backend solo tramite i binding Wails (<code>src/app/api.ts</code> → <code>wailsjs/go/app/*</code>, che chiamano <code>window.go.app[Svc][Method]</code>), più gli eventi <code>window.runtime.EventsOn*</code>;</li><li>il mock e2e (<code>src/test/wails-mock</code>) installa proprio <code>window.go</code>/<code>window.runtime</code> e fa già girare l&#39;intera UI in un browser.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><p><strong>Il browser è un dispositivo come gli altri.</strong></p><ul><li>Il workbench web registra un dispositivo (<code>POST /me/devices</code>, <code>platform: &quot;web&quot;</code>, uno per profilo del browser, id in IndexedDB), revocabile da Dispositivi.</li><li>Apre un vault cloud con lo stesso flusso di &quot;Collega vault esistente&quot;: copia locale in OPFS, pull, indice locale, commit con <code>base_rev</code>, merge sul client.</li><li>Il protocollo di sync e le API restano invariati: nessuna API di contenuto nuova, il server resta cieco al contenuto.</li></ul></li><li><p><strong>Stessa logica, stessa UI.</strong></p><ul><li>La logica è il core Go del desktop compilato in WASM ed eseguito in un Web Worker (ADR-0030).</li><li>La UI è quella del desktop, estratta in <code>packages/workbench</code> (<code>@memobrain/workbench</code>) e condivisa dalle due app.</li><li>Un bridge in <code>web/src/workbench/</code> installa <code>window.go</code>/<code>window.runtime</code> sopra un RPC verso il worker: i binding generati non cambiano.</li></ul></li><li><p><strong>Route.</strong></p><ul><li><code>/vaults/:id/open</code>, raggiungibile dal pulsante &quot;Apri&quot; in &quot;I miei vault&quot; e sui mount.</li><li>Il chunk del workbench è caricato in modo lazy; la console resta entro il suo budget (ADR-0020) e il workbench ha un budget separato.</li></ul></li><li><p><strong>Online-first con cache.</strong></p><ul><li>Copia del vault e database (<code>index.db</code>, <code>sync.db</code>) in OPFS.</li><li>Le modifiche fatte durante brevi disconnessioni restano in coda (outbox del sync engine).</li><li>Nessun service worker né installazione PWA: serve una sessione OIDC valida.</li></ul></li><li><p><strong>Una scheda per vault.</strong> Un Web Lock per vault (gli handle sincroni OPFS sono esclusivi). Una seconda scheda mostra &quot;vault aperto in un&#39;altra scheda&quot;, come l&#39;istanza singola del desktop.</p></li><li><p><strong>Vault privati modificabili.</strong></p><ul><li>Sblocco con passphrase o recovery key (<code>VaultCryptoAPI.Unlock</code>, stessa UI del desktop).</li><li>La VMK resta solo in memoria nel worker.</li><li>Blocco per inattività (default 15 min, configurabile nel Config Profile).</li><li>Al blocco, al logout e con &quot;Dimentica questo browser&quot; la copia OPFS in chiaro del vault privato viene <strong>cancellata</strong>: sul web il dato decifrato non sopravvive alla sessione.</li></ul></li><li><p><strong>Eccezioni di parità</strong> (non applicabili al web, elencate in <code>docs/web-workbench-parity.md</code>):</p><table tabindex="0"><thead><tr><th>Funzione desktop</th><th>Sul web</th></tr></thead><tbody><tr><td>Updater</td><td>Non serve: la Web UI è servita dal cloud</td></tr><tr><td>Vault su cartella locale (<code>PickFolder</code>, &quot;Apri un&#39;altra cartella&quot;)</td><td>Solo vault cloud</td></tr><tr><td>Controllo della cifratura del disco</td><td>Non applicabile</td></tr><tr><td>Deep link <code>memobrain://</code></td><td>Route URL</td></tr><tr><td>Finestra nativa e schermo intero</td><td>Fullscreen API</td></tr><tr><td>Dialoghi nativi di salvataggio e stampa</td><td><code>showSaveFilePicker</code> o download Blob, <code>window.print()</code></td></tr><tr><td>Selezione di file per l&#39;importer</td><td><code>&lt;input type=file&gt;</code> / <code>showDirectoryPicker</code></td></tr></tbody></table><p>Ogni altra funzione (editor nelle tre modalità, ricerca, link e rename, grafo, canvas, Excalidraw, Bases, template, daily e unique note, composer, segnalibri, workspace, slide, export, importer, history locale e cloud, conflitti, condivisione, impostazioni, hotkey, palette) deve essere presente, con un test in <code>web</code> che la copre.</p></li><li><p><strong>Sicurezza della pagina.</strong></p><ul><li>CSP dedicata alla route del workbench, derivata da quella di produzione del desktop (<code>apps/desktop/internal/app/csp_prod.go</code>): <code>script-src &#39;self&#39; &#39;wasm-unsafe-eval&#39;</code>, <code>worker-src &#39;self&#39;</code>, <code>connect-src &#39;self&#39; &lt;issuer&gt;</code>, <code>frame-ancestors &#39;none&#39;</code>.</li><li>Gli stili dinamici di CodeMirror ed Excalidraw sono ammessi solo su quella route (nonce dove la libreria lo supporta, altrimenti <code>&#39;unsafe-inline&#39;</code> limitato agli stili).</li><li>Gli asset hanno SRI; la sanificazione con DOMPurify è invariata (V-02).</li><li>La console continua a usare la CSP attuale.</li></ul></li><li><p><strong>Feature flag.</strong> <code>web_workbench</code> nel Config Profile (feature, acceso di default) (default <code>true</code>) permette all&#39;amministratore di disattivare il workbench per gruppo.</p></li></ol><h2 id="proposta-di-modifica-dello-spec" tabindex="-1">Proposta di modifica dello spec <a class="header-anchor" href="#proposta-di-modifica-dello-spec" aria-label="Permalink to &quot;Proposta di modifica dello spec&quot;">​</a></h2><ul><li><strong>A-03:</strong> &quot;La Web UI del cloud comprende console amministrativa, area utente e un workbench del vault con le stesse funzioni del client desktop, salvo le eccezioni di ADR-0029 (updater, vault su cartella locale, integrazioni native del sistema operativo). Il workbench web è un dispositivo di sync come gli altri: online-first, con cache locale nel browser.&quot;</li><li><strong>§0.1 punto 3:</strong> aggiungere &quot;workbench del vault (modifica nel browser)&quot;.</li><li><strong>§2.8.2:</strong> nuova schermata &quot;Apri vault&quot; con il rimando a ADR-0029.</li><li><strong>§4.4:</strong> aggiungere <code>src/workbench/</code> (bridge e worker) e il pacchetto <code>packages/workbench</code>.</li><li><strong>§3.8.1 e tabella rischi:</strong> &quot;JavaScript servito dal server&quot; vale ora anche per la scrittura dei vault privati. Mitigazioni: CSP, SRI, blocco per inattività, cancellazione della cache in chiaro, possibilità di disattivare il workbench con il feature flag; il client desktop firmato resta il percorso ad alta fiducia.</li></ul><h2 id="esito-dell-implementazione-m9-wp5-2026-10-29" tabindex="-1">Esito dell&#39;implementazione (M9-WP5, 2026-10-29) <a class="header-anchor" href="#esito-dell-implementazione-m9-wp5-2026-10-29" aria-label="Permalink to &quot;Esito dell&#39;implementazione (M9-WP5, 2026-10-29)&quot;">​</a></h2><p>Scostamenti dalla decisione scritta sopra, emersi realizzandola:</p><ul><li><strong>Pagina a sé.</strong> Il workbench non è una route lazy della SPA ma il documento <code>workbench.html</code>, servito per <code>/vaults/:id/open</code>: il CSS di un chunk dinamico finisce nel bundle dell&#39;ingresso (esbuild non lo separa) e lo stile globale della UI desktop avrebbe cambiato la console. &quot;Apri&quot; è un link con caricamento completo; anche il ritorno al login passa da un caricamento completo.</li><li><strong>Un workbench per browser</strong> (Web Lock <code>memobrain-workbench</code>), non per vault, perché gli handle sincroni di OPFS e il pool di SQLite sono esclusivi per l&#39;origine.</li><li><strong>Cancellazione della copia in chiaro</strong> (punto 6): implementata per il blocco e per l&#39;inattività (15 minuti, fissi) in <code>launch.ts</code> (<code>lockAndForget</code>: <code>VaultCryptoAPI.Lock</code>, <code>CloseVault</code>, rimozione della cartella OPFS e dei database del vault); il logout e «Dimentica questo browser» sono fatti in WP7 (<code>forgetThisBrowser</code>: rimuove la cartella OPFS <code>fs</code> e il pool SQLite; si ferma se un workbench è aperto in un&#39;altra scheda, perché ne tiene bloccati i file).</li><li><strong>CSP</strong> (punto 8): la politica dedicata è in <code>web-embed.WorkbenchCSP</code>; <code>worker-src &#39;self&#39; blob:</code> e <code>connect-src &#39;self&#39; blob:</code> più l&#39;issuer bastano (verificato in un browser vero: nessuna violazione). <code>blob:</code> in <code>connect-src</code> serve ai download e alle risorse del vault; in <code>worker-src</code> serve solo al worker del core (vedi SRI). La console non ammette <code>blob:</code>.</li><li><strong>SRI</strong> (punto 8, rivisto 2026-11-01). Cosa è verificato e cosa no: <ul><li><strong>Console:</strong> è costruita senza code splitting, quindi è un solo file JS più un CSS, entrambi con <code>integrity</code> nel tag. Tutto il codice della console è coperto (non ha parti lazy, il budget non cambia).</li><li><strong>Worker del core</strong> (Go WASM, sync, VMK): <code>new Worker()</code> non accetta <code>integrity</code>. La pagina scarica lo script con <code>fetch(url, { integrity })</code>, usando lo SHA-384 calcolato dalla build e incluso nel bundle del workbench (a sua volta caricato con SRI), e avvia il worker da un URL <code>blob:</code> dei byte verificati (<code>VerifiedWorker</code> in <code>bridge.ts</code>). Uno script alterato non parte e la pagina mostra l&#39;errore (test in <code>e2e-security/workbench-csp.spec.ts</code>). Il bundle del worker deve restare autosufficiente, senza import (la build lo controlla), e risolvere gli URL su <code>location.origin</code>.</li><li><strong>WASM</strong> (core e sqlite): <code>fetchChecked</code> nel worker usa sempre l&#39;<code>integrity</code> registrata dalla build. Un hash mancante è un errore, non un controllo saltato; solo le build E2E (<code>MEMOBRAIN_E2E</code>, costante eliminata in produzione) lo ammettono. La catena pagina → worker → WASM è quindi verificata per intero.</li><li><strong>Chunk, worker ed Excalidraw</strong> (chiusura delle lacune, W8 lotto C2, 2026-11-01). Il code splitting resta (tutto nel file iniziale porterebbe il workbench da circa 2,5 MB a circa 12,8 MB, oltre il budget di ADR-0020), e i chunk sono fissati da un <strong>import map</strong> inline in <code>workbench.html</code> con il campo <code>integrity</code> per ogni chunk JS della build, statico o lazy (Chromium 127+, Firefox 138+; gli altri browser ignorano il campo). È l&#39;unico script inline della pagina: <code>web-embed</code> calcola all&#39;avvio lo SHA-256 dell&#39;import map dal <code>workbench.html</code> incorporato e lo aggiunge a <code>script-src</code> della <code>WorkbenchCSP</code> (<code>ImportMapHashes</code>); <code>&#39;unsafe-inline&#39;</code> resta vietato. Lo script classico <code>/excalidraw-assets/excalidraw.js</code> è aggiunto da un tag con <code>integrity</code>; il worker del layout del grafo (ora con nome hashato) e quello di pdf.js partono, come il core, da un URL <code>blob:</code> dei byte scaricati con <code>fetch</code> + <code>integrity</code> (<code>web/src/workbench/sri.ts</code>). Il collegamento è fatto dalla build web (plugin <code>verified-loaders</code> in <code>web/scripts/esbuild.mjs</code>), senza toccare il comportamento del desktop: per il layout la build sostituisce la chiamata <code>new Worker(&#39;/assets/layout.worker.js&#39;)</code> di <code>graph/layoutHost.ts</code> e fallisce se non la trova. Test: <code>TestEveryEmbeddedScriptIsPinned</code> (ogni script della build è raggiungibile da una catena di SRI che parte dalle pagine) e gli e2e di <code>e2e-security</code> con chunk, worker di pdf.js ed <code>excalidraw.js</code> alterati. Nessuno script della build resta senza verifica nei browser che supportano l&#39;<code>integrity</code> dell&#39;import map.</li><li><strong>Limite di fondo:</strong> SRI protegge da file alterati tra il server e il browser (cache, CDN, proxy) o sostituiti nello storage degli asset. Non protegge da un server d&#39;origine compromesso, che serve anche l&#39;HTML con gli hash: per i vault privati il percorso ad alta fiducia resta il client desktop firmato.</li></ul></li><li><strong>Feature flag</strong> (punto 9): si chiama <code>web_workbench</code> (le feature del Config Profile sono booleani piatti) ed è implementato in WP6, acceso di default.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Web UI di sola consultazione</strong>: scartata, non soddisfa la parità richiesta.</li><li><strong>Port della logica in TypeScript</strong>: scartato in ADR-0030 (due implementazioni da tenere allineate).</li><li><strong>Calcolo lato server (indice e ricerca nel cloud)</strong>: scartato. Viola §3.4.1, non funziona sui vault privati E2EE e sposta il carico sul server.</li><li><strong>Workbench solo per i vault condivisi</strong>: scartato dall&#39;owner, che vuole anche i privati.</li><li><strong>PWA offline completa</strong>: rinviata. Richiede token offline, aggiornamento controllato degli asset e una politica di conservazione dei dati in chiaro che oggi non c&#39;è.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>La Web UI diventa un client di sync completo. Gli e2e e i test di sync devono coprire anche il browser (web ↔ desktop, conflitti <code>.md</code> fusi, copie di conflitto per <code>.canvas</code>/<code>.excalidraw</code>).</li><li>Lo spostamento del frontend in <code>packages/workbench</code> tocca molti file, ma è meccanico. Il desktop deve restare verde a ogni passo (<code>make e2e</code>, build Wails).</li><li>Il bundle del workbench è grande (WASM, Excalidraw, mermaid, pdfjs). È accettato con caricamento lazy e budget separato.</li><li>Il modello di fiducia della Web UI si allarga alla scrittura dei vault privati. Il limite è documentato e mitigato; l&#39;audit crittografico esterno (M7-WP2) deve includerlo.</li><li>Da rivalutare dopo il primo rilascio: PWA offline, apertura di più vault in schede diverse, condivisione della cache tra schede.</li></ul><p><strong>Aggiornamento 2026-11-02:</strong> l&#39;owner ha accettato l&#39;ADR, recepito in <code>Specifications.md</code> v1.3 (A-03 riscritta, §1.7 e §2.8.3 nuove). Il punto 6 della decisione e l&#39;«Esito» descrivono una politica superata dall&#39;onda W3 di M11: il timer di inattività è uno solo, quello del core (<code>security.vault_lock_minutes</code>, non 15 minuti fissi in <code>launch.ts</code>), e al blocco manuale o per inattività la copia in chiaro si cancella solo se non ci sono modifiche da inviare né conflitti, altrimenti un overlay chiede cosa fare; si aggiungono lo sweep all&#39;avvio e l&#39;unlock gate (spec §2.8.3, <code>docs/desktop-web-sync.md</code>).</p>',21)])])}const b=o(l,[["render",n]]);export{g as __pageData,b as default};
